import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";
import { StatusPillComponent } from "../../lib/status-pill.component";

@Component({
    selector: "app-feature-10",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, StatusPillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 10" [disableTooltip]="true">
            @for (item of items; track item.id) {
                <app-pill [label]="item.name" [variant]="item.variant" [hideHint]="item.hidden" />
            }
            <app-pill label="Plain" hideHint />
            <app-pill variant="success" label="Active" [hideHint]="!isActive" />
            <app-fancy-pill #fancyRef label="Fancy" icon="star" [disableTooltip]="!isActive" />
            <small>Fancy hint: {{ fancyRef.disableTooltip() ? 'off' : 'on' }}</small>
            <app-status-pill disableTooltip label="Status" variant="success"></app-status-pill>
        </app-card>
        <app-card heading="Summary" [disableTooltip]="!isActive" />
    `
})
export class Feature010Component {
    isActive = true;
    count = 3;
    title = "Title 10";
    statusVariant: PillVariant = "success";
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: true } ];
}

